import struct, wave, os, hashlib

def parse_wav(path):
    """Parse wav file, return dict with params and pcm, or None if not wav"""
    try:
        data = open(path,"rb").read() if path not in ("pipe:0", "pipe:", "-") else None
    except:
        return None
    # For pipe input, read from stdin? Actually for test, just handle file
    if data is None:
        return None
    if len(data)<12 or data[0:4]!=b'RIFF' or data[8:12]!=b'WAVE':
        # Check for RF64? Ignore
        return None
    # Walk chunks
    pos=12
    fmt=None
    lst_encoder=None
    pcm_data=None
    data_size=None
    while pos+8 <= len(data):
        cid=data[pos:pos+4]
        sz=int.from_bytes(data[pos+4:pos+8],'little')
        # Handle RF64 with 0xFFFFFFFF? For pipe, sizes are FFFFFFFF, need to handle
        chunk_data=data[pos+8:pos+8+sz] if sz!=0xFFFFFFFF else data[pos+8:]
        if cid==b'fmt ':
            # fmt: audioformat, channels, rate, byterate, blockalign, bits
            if len(chunk_data)>=16:
                af, ch, rate, br, ba, bits = struct.unpack('<HHIIHH', chunk_data[:16])
                fmt=(af,ch,rate,br,ba,bits)
        elif cid==b'LIST':
            # Look for INFO ISFT
            # LIST data: 4 INFO + ...
            if len(chunk_data)>=4 and chunk_data[0:4]==b'INFO':
                # Walk subchunks inside LIST? LIST size includes INFO?
                # Actually LIST chunk data starts with INFO (4), then subchunks
                subpos=4
                while subpos+8 <= len(chunk_data):
                    subid=chunk_data[subpos:subpos+4]
                    subsz=int.from_bytes(chunk_data[subpos+4:subpos+8],'little')
                    subdata=chunk_data[subpos+8:subpos+8+subsz]
                    if subid==b'ISFT':
                        # Strip null and padding?
                        try:
                            lst_encoder=subdata.rstrip(b'\x00').decode(errors='replace')
                        except:
                            lst_encoder=None
                    subpos+=8+subsz+(subsz%2)
        elif cid==b'data':
            if sz==0xFFFFFFFF:
                # pipe: rest is data
                pcm_data=data[pos+8:]
                data_size=len(pcm_data)
            else:
                pcm_data=data[pos+8:pos+8+sz]
                data_size=sz
        # Move, handling padding and FFFFFFFF
        if sz==0xFFFFFFFF:
            break
        pos+=8+sz+(sz%2)
        if pos>=len(data):
            break
    if fmt is None or pcm_data is None:
        return None
    af,ch,rate,br,ba,bits=fmt
    # Compute nframes
    sampwidth=bits//8
    nframes=len(pcm_data)//(ch*sampwidth) if ch*sampwidth!=0 else 0
    return {"audioformat":af,"channels":ch,"rate":rate,"byterate":br,"blockalign":ba,"bits":bits,"pcm":pcm_data,"encoder":lst_encoder,"filesize":len(data),"nframes":nframes,"sampwidth":sampwidth}

