import struct

class BitReader:
    def __init__(self, data):
        self.data=data
        self.pos=0
        self.len=len(data)*8
    def read(self, n):
        if n==0:
            return 0
        v=0
        for _ in range(n):
            if self.pos>=self.len:
                raise EOFError("out of bits")
            byte=self.data[self.pos//8]
            bit=(byte >> (7-(self.pos%8))) & 1
            v=(v<<1)|bit
            self.pos+=1
        return v
    def read_signed(self, n):
        v=self.read(n)
        if n>0 and (v & (1<<(n-1))):
            v -= (1<<n)
        return v
    def read_unary(self):
        c=0
        while True:
            b=self.read(1)
            if b==1:
                break
            c+=1
            if c>100000:
                raise ValueError("unary too large")
        return c

def decode_rice_partition(br, param_bits, n_samples, bps):
    # param_bits is Rice param (0..14 for Rice, 0..30 for Rice2, 15/31 is escape)
    # For escape, caller handles
    out=[]
    for _ in range(n_samples):
        q=br.read_unary()
        r=br.read(param_bits) if param_bits>0 else 0
        code=(q<<param_bits)|r
        # sign decode: (code>>1) ^ -(code&1)
        if code & 1:
            s= -((code>>1)+1)
        else:
            s= code>>1
        out.append(s)
    return out

