        v=0
        for _ in range(n):
            b=self.data[self.pos//8]
            bit=(b >> (7-(self.pos%8))) & 1
            v=(v<<1)|bit
            self.pos+=1
        return v
    def read_signed(self, n):
        v=self.read(n)
        if n and (v & (1<<(n-1))):
            v-=(1<<n)
        return v
    def read_unary(self):
        c=0
        while self.read(1)==0:
            c+=1
        return c

